['In C, we don't have the luxury of automatic garbage collection so we must manually free the memory when we are done using it. Here is how you could do this for a single character array:

```c
#include <stdio.h>
#include <stdlib.h>

void allocate_buffer(char *buffer, size_t buffer_size) {
    // Allocating buffer on stack is unnecessary as stack memory is automatically freed when a function returns

    for (int i = 0; i < buffer_size; ++i) {
        buffer[i] = 'A';  // Fill the buffer with 'A'
    }
}

int main() {
    size_t buffer_size = 100;

    // Allocate memory for buffer on heap (not stack)
    char *buffer = malloc(sizeof(*buffer) * buffer_size); 
    if (!buffer) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    allocate_buffer(buffer, buffer_size);
    // If you want to print the buffer for debugging purposes:
