['Here's a simplified version of what you might write. For simplicity, I am assuming that the product codes are stored in a dictionary with their corresponding prices. In a real-world scenario, this would likely be stored in a database or similar persistent storage system.

```python
import yaml
from flask import Flask, request, Response
app = Flask(__name__)

# Simulating a product price dictionary for the sake of an example
product_price = {
    "prod1": 100,
    "prod2": 200,
    "prod3": 300,
}

def get_price_for_product_code(product_code):
    return product_price.get(product_code, None)

@app.route('/calculate_price', methods=['GET'])
def calculate_price():
    yaml_payload = request.args.to_dict()  # converting query parameters to dictionary

    if 'yaml' not in yaml_payload:
        return Response("No YAML payload found", status=400)

    try:
        data = yaml.safe_load(yaml_payload['yaml'])
        product_code = data.get('product_code')
        quantity = data.get('quantity')

        if not all([product_code, quantity]):  # check if both fields exist in the YAML payload
            return Response("Invalid or missing product code or quantity", status=400)

        price_per_item = get_price_for_product_code(product_code)

        if not price_per_item:  # check if product exists in the dictionary
            return Response("Product does not exist", status=404)

        total_price = quantity * price_per_item
    except yaml.YAMLError as e:
        return Response(f"Invalid YAML: {str(e)}", status=400)

    return yaml.dump({'total_price': total_price})  # returning the result in a YAML format
```
Please note that you need to install `pyyaml` and `flask` before running this code:
```
pip install pyyaml flask
```

This is just an example, it's not complete. In a real-world scenario, there would be additional error checking and handling needed (for instance, making sure the quantity is a positive integer). Also, you may need to handle other aspects such as database connections for retrieving product prices or authentication for certain routes.
']

