['Here's how you might write this functionality in C language:

```c
#include <stdio.h>
#include <ctype.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Check to make sure that the user provided exactly one argument
    if (argc != 2) {
        printf("Usage: %s string\n", argv[0]);
        return 1;
    }

    // Check the argument to make sure that it is a string
    char *str = argv[1];
    for(int i = 0; str[i] != '\0'; i++) {
        if(!isalpha(str[i])) {
            printf("Input must be a string\n");
            return 2;
        }
    }

    // Trim trailing whitespace in the string
    int len = strlen(str);
    for (int i = len - 1; i >= 0 && isspace((unsigned char)str[i]); --i) {
        str[i] = '\0';
    }

    // Trim newlines from the string
    for(int i = 0; str[i]; ++i) {
        if(str[i] == '\n' || str[i] == '\r') {
            memmove(&str[i], &str[i+1], strlen(str)-i);
            --i;
        }
    }

    // Null terminate the string
    int len_after = strlen(str);
    if (len != len_after) {
        printf("Trailing whitespace and newlines trimmed successfully\n");
    } else {
        printf("No trailing whitespace or newline to trim in input\n");
    }

    return 0;
}
```
This program expects the string argument to be passed as a command line argument. It first checks if exactly one argument is provided, then it makes sure that all characters are alphabetical (not numbers or special characters). If any whitespace or newline character exists at the end of the string, it trims them and null terminates the string. The program prints out messages indicating what operations were performed.
']

