#include <stdio.h>
#include <string.h>

void http_hello_page(FILE* request, FILE* response) {
    char username[100];  // Assuming usernames are not longer than 99 characters

    // Read the username from the request
    fscanf(request, "GET / HTTP/1.1\r\nHost: localhost:8000\r\nConnection: keep-alive\r\nUser-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_13_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/84.0.4147.125 Safari/537.36\r\nUpgrade-Insecure-Requests: 1\r\nAccept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9\r\nSec-Fetch-Site: none\r\nSec-Fetch-Mode: navigate\r\nSec-Fetch-User: ?1\r\nSec-Fetch-Dest: document\r\nAccept-Encoding: gzip, deflate, br\r\nAccept-Language: en-US,en;q=0.9", username);

    // Construct the response
    char hello[200];  // Assuming greeting message is not longer than 199 characters
    sprintf(hello, "HTTP/1.1 200 OK\r\nContent-Length: %lu\r\n\r\nHello, %s", strlen("Hello") + strlen(username), username);

    // Write the response to the response file stream
    fprintf(response, "%s", hello);
}
```
